-- BINOFIT — Seed massif de démonstration (Supabase Postgres, schéma specs/schema.sql).
--
-- Contenu : 120 users (20 par zone de public/src/services/location.ts), leurs sports
-- (les 11 sports et les 4 niveaux représentés), 2 à 4 disponibilités chacun, 250 activities
-- (en_attente, acceptee, refusee, terminee), 60 conversations à 2 participants (40 liées
-- à une activité acceptée ou terminée, 20 directes) et leurs messages.
--
-- Tous les identifiants texte commencent par « seed- ». user_sports, user_availability et
-- participants n'ont pas d'id texte : ils sont rattachés à un user ou une conversation
-- « seed- » et partent avec lui (on delete cascade). Les e-mails utilisent le domaine
-- réservé .invalid : aucun ne peut exister. Les dates sont relatives à now() pour que
-- les activités à venir restent à venir au moment de l'exécution.
--
-- À lancer dans Supabase > SQL Editor (rôle postgres, qui n'est pas soumis à la RLS).
-- Relançable : le script supprime d'abord les données « seed- » existantes.
-- Nettoyage : specs/seed-supprimer.sql.
-- Fichier généré : ne pas éditer à la main les blocs INSERT.

begin;

-- 0. Nettoyage préalable (même logique que specs/seed-supprimer.sql)
delete from favorites where user_id like 'seed-%' or target_id like 'seed-%';
delete from messages where conversation_id like 'seed-%' or sender_id like 'seed-%';
delete from conversations where id like 'seed-%';
delete from activities where id like 'seed-%' or created_by like 'seed-%' or guest_id like 'seed-%';
delete from users where id like 'seed-%';

-- 1. users

-- 2. user_sports

-- 3. user_availability (id généré par Postgres)

-- 4. activities

-- 5. conversations

-- 6. participants

-- 7. messages

commit;
